import os,sys,json
from playwright.sync_api import sync_playwright
# Panyard VR 💡 Ideas: a pad (menu → 💡 Ideas) with a blank score that writes the notes you hit on the pans (the length
# you picked, two notes together as a chord, rests, undo, ▶ plays it back on the pans), a typing page with a keyboard on the
# pad, and a drawing page for the beam. Ideas are kept on the headset and listed on the page's Songs tab.
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
D=os.environ['WORK']+'/tvrideas/';os.makedirs(D,exist_ok=True)
fails=[]
def check(ok,what):
    print(('ok   ' if ok else 'FAIL ')+what)
    if not ok:fails.append(what)
def route(r):
    u=r.request.url.split('?')[0].replace('https://pan.test/','')
    f=os.path.join(ROOT,'source','band-sounds',u.split('/')[-1]) if u.startswith('band/band-sounds/') else os.path.join(ROOT,u if not u.endswith('/') else u+'index.html')
    return r.fulfill(path=f) if os.path.exists(f) else r.fulfill(status=404,body='')
with sync_playwright() as p:
    b=p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required','--use-gl=swiftshader','--enable-unsafe-swiftshader'])
    pg=b.new_page(viewport={'width':1280,'height':800});errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.add_init_script("if(!sessionStorage.getItem('s')){localStorage.setItem('panyard-vr-welcomed','1');localStorage.setItem('panyard-vr-yard','0');sessionStorage.setItem('s','1')}")
    pg.route('https://pan.test/**',route)
    import base64
    save=lambda n:open(D+n+'.png','wb').write(base64.b64decode(pg.evaluate('VR.ideas.png()').split(',')[1]))
    load=lambda:(pg.wait_for_function("window.VR&&VR.ready()>=79&&VR.drums()>0",timeout=90000),pg.evaluate("document.getElementById('hud').hidden=true"))
    pg.goto('https://pan.test/vr/');load()
    check('mideas' in pg.evaluate("VR.menuHits()"),'the menu has a 💡 Ideas button')
    pg.evaluate("VR.ideas.press('mideas')")
    check(pg.evaluate("VR.ideas.ia().len")=='auto','lengths come from your timing (⏱ Auto) unless you pick one')
    pg.evaluate("VR.ideas.press('ialen:1')")
    check(pg.evaluate("VR.ideas.shown()") and pg.evaluate("VR.ideas.live()"),'it opens the pad, and the beam can press it')
    st=pg.evaluate("VR.ideas.state()");check(len(st['list'])==1 and st['list'][0]['title']=='Idea 1','a first, empty idea is ready')
    hit=lambda i:pg.evaluate(f"VR.players.hitCopy('tenor',0,'{i}',2.5)")
    notes=lambda:pg.evaluate("VR.ideas.state().list[0].notes")
    for i in ['tenor:60','tenor:62','tenor:64']:hit(i);pg.wait_for_timeout(150)
    n=notes();check([x['m'] for x in n]==[60,62,64] and [x['b'] for x in n]==[0,1,2],f'C4 D4 E4 hit on the pans are written as C4 D4 E4, a beat each {[(x["m"],x["b"]) for x in n]}')
    pg.evaluate("VR.ideas.press('ialen:0.5')");hit('tenor:65');pg.wait_for_timeout(150);hit('tenor:67');pg.wait_for_timeout(150)
    n=notes();check(n[-1]['d']==.5 and n[-1]['b']==3.5,'Eighth: the next notes are half a beat each')
    pg.evaluate("VR.ideas.press('ialen:2')");pg.evaluate("VR.players.hitCopy('tenor',0,'tenor:60',2.5);VR.players.hitCopy('tenor',0,'tenor:64',2.5)")
    n=notes();check(len(n)==7 and n[-1]['b']==n[-2]['b']==4 and n[-1]['d']==2,'two notes hit together stack as a chord (a half note)')
    pg.evaluate("VR.ideas.press('iarest')");n=notes();check(n[-1].get('rest') and n[-1]['b']==6,'Rest adds a rest after them')
    pg.evaluate("VR.ideas.press('iaundo')");pg.evaluate("VR.ideas.press('iaundo')");n=notes();check(len(n)==5,'⌫ Undo takes off the rest, then the whole chord')
    pg.evaluate("VR.ideas.press('iawrite')");hit('tenor:72');pg.wait_for_timeout(150);check(len(notes())==5,'with Writing off you can play without writing')
    pg.evaluate("VR.ideas.press('iawrite')");pg.evaluate("VR.ideas.press('ialen:1')")
    for i in ['tenor:72','tenor:71','tenor:69','tenor:67','tenor:65','tenor:64','tenor:62','tenor:60','tenor:62','tenor:64']:hit(i);pg.wait_for_timeout(120)
    pg.evaluate("VR.ideas.open(true);VR.ideas.noSticks()");pg.wait_for_timeout(500);pg.screenshot(path=D+'score.png');save('pad-score')
    pg.evaluate("VR.ideas.press('iawrite')")   # Writing off: just play it back, no count-in
    pg.evaluate("VR.hits.length=0;VR.ideas.press('iaplay')");pg.wait_for_timeout(300);check(pg.evaluate("VR.ideas.ia().playing"),'▶ Play plays the score')
    pg.wait_for_timeout(1500);played=pg.evaluate("VR.hits.filter(h=>h.p).map(h=>h.id)")
    check(played[:3]==['tenor:60','tenor:62','tenor:64'],f'on the pans, in order {played[:5]}')
    check(len(played)<12,f'notes are handed out as they come, not all at once ({len(played)} so far)')
    check(len(notes())==15,'playing back writes nothing new')
    pg.evaluate("VR.ideas.press('iaplay')");check(not pg.evaluate("VR.ideas.ia().playing"),'■ Stop stops it')
    n0=pg.evaluate("VR.hits.length");pg.wait_for_timeout(1200);n1=pg.evaluate("VR.hits.length")
    check(n1==n0,f'and after ■ Stop no more notes come ({n1-n0} came)')
    check(not pg.evaluate("VR.ideaChans()"),'the notes still ringing are faded out')
    pg.evaluate("VR.hits.length=0;VR.ideas.press('iaplay')");pg.wait_for_timeout(700);pg.evaluate("VR.ideas.press('iaplay');VR.ideas.press('iaplay')");pg.wait_for_timeout(900)
    ids=pg.evaluate("VR.hits.filter(h=>h.p).map(h=>h.id)");check(ids.count('tenor:60')<=2 and pg.evaluate("VR.ideas.ia().playing"),f'▶ again starts it once, fresh, with no copy on top {ids[:6]}')
    pg.evaluate("VR.ideas.press('iaplay')")
    pg.evaluate("VR.ideas.press('iawrite')")
    c0=pg.evaluate("VR.clicks");pg.evaluate("VR.ideas.press('iaclick')");pg.wait_for_timeout(1500);c1=pg.evaluate("VR.clicks")
    check(c1-c0>=2,f'🥁 Metronome ticks on its own while you write ({c1-c0} clicks)')
    pg.evaluate("VR.ideas.press('iaplay')");pg.wait_for_timeout(4500);check(pg.evaluate("VR.ideas.ia().playing"),'with Writing on, ▶ keeps going (the metronome with it) until ■ Stop')
    pg.evaluate("VR.ideas.press('iaplay')");pg.evaluate("VR.ideas.press('iaclick')");c2=pg.evaluate("VR.clicks");pg.wait_for_timeout(1000)
    check(pg.evaluate("VR.clicks")-c2<=1,'and the metronome goes quiet when switched off')
    for _ in range(30):hit('tenor:60');pg.wait_for_timeout(95)
    check(pg.evaluate("VR.ideas.ia().page")==1,'past bar 8 the score turns to the next page by itself')
    pg.evaluate("VR.ideas.press('iapg:-1')");check(pg.evaluate("VR.ideas.ia().page")==0,'◀ goes back to bars 1–8')
    # bass pans write on the bass clef: tested by drawing; just check a bass idea draws without errors
    pg.evaluate("VR.ideas.press('ianew')");pg.evaluate("VR.ideas.press('iatab:type')")
    check(len(pg.evaluate("VR.ideas.state().list"))==2,'＋ New starts a second idea')
    for k in ['c','space','⇧','g','space','⇧','a','m','⏎']:pg.evaluate(f"VR.ideas.press('iakey:{k}')")
    pg.evaluate("VR.ideas.type('verse two, the bass walks down')")
    t=pg.evaluate("VR.ideas.state().list[0].text");check(t=='C G Am\nVerse two, the bass walks down',f'the keyboard types (capitals after a new line) {t!r}')
    pg.evaluate("VR.ideas.press('iakey:⌫')");check(pg.evaluate("VR.ideas.state().list[0].text").endswith('dow'),'⌫ deletes a letter')
    pg.wait_for_timeout(300);pg.screenshot(path=D+'type.png');save('pad-type')
    pg.evaluate("VR.ideas.press('iatab:draw')")
    pg.evaluate("VR.ideas.pen([[200,300],[260,340],[320,300],[380,340],[440,300]])")
    pg.evaluate("VR.ideas.press('iaink:1')");pg.evaluate("VR.ideas.beam(600,400,true);VR.ideas.beam(700,500);VR.ideas.beam(800,420);VR.ideas.beam(0,0,false)")
    ink=pg.evaluate("VR.ideas.state().list[0].ink");check(len(ink)==2 and len(ink[1]['p'])==3 and ink[1]['c']=='#f6ba45',f'the beam draws lines, in the colour picked ({len(ink)} lines)')
    pg.wait_for_timeout(300);pg.screenshot(path=D+'draw.png');save('pad-draw')
    pg.evaluate("VR.ideas.press('iainkundo')");check(len(pg.evaluate("VR.ideas.state().list[0].ink"))==1,'↶ Undo line takes the last line off')
    pg.evaluate("VR.ideas.press('iaclr')");check(len(pg.evaluate("VR.ideas.state().list[0].ink"))==1,'🗑 Clear asks first')
    pg.evaluate("VR.ideas.press('iaclr')");check(len(pg.evaluate("VR.ideas.state().list[0].ink"))==0,'and clears on the second press')
    pg.evaluate("VR.ideas.press('iaprev:1')");check(len(pg.evaluate("VR.ideas.state().list.find(e=>e.title=='Idea 1').notes"))==45,'▶ flips back to the first idea, its score kept')
    # ⏱ Auto: play at your own pace, 90 bpm = 2/3 s a beat
    pg.evaluate("VR.ideas.press('ianew');VR.ideas.press('iatab:score');VR.ideas.press('ialen:auto')")
    B=2/3
    for i,(nid,beat) in enumerate([('tenor:60',0),('tenor:62',1),('tenor:64',2),('tenor:65',2.5),('tenor:67',3.04),('tenor:69',4.97),('tenor:71',8.5)]):
        pg.evaluate(f"VR.ideas.hitAt('{nid}',{10+beat*B})")
    n=pg.evaluate("VR.ideas.state().list.find(e=>e.title=='Idea 3').notes")
    got=[(x.get('m'),x['b'],x['d']) for x in n]
    check([x for x in got if x[0]][:6]==[(60,0,1),(62,1,1),(64,2,.5),(65,2.5,.5),(67,3,2),(69,5,3)],f'each note is as long as the wait for the next, snapped to eighths {got}')
    check(any(x[0] is None and x[1]==8 and x[2]==.5 for x in got),'what is left over becomes a rest')
    check(got[-1][:2]==(71,8.5),'the newest note waits (a quarter) for the next one')
    pg.evaluate(f"VR.ideas.hitAt('tenor:72',{10+8.5*B+6})")
    n=pg.evaluate("VR.ideas.state().list.find(e=>e.title=='Idea 3').notes");check(n[-1]['b']==9.5,f'after a long pause a new phrase starts right after what is written ({n[-1]["b"]})')
    pg.evaluate("VR.ideas.hitAt('tenor:76',"+str(10+8.5*B+6+.02)+")");n=pg.evaluate("VR.ideas.state().list.find(e=>e.title=='Idea 3').notes")
    check(n[-1]['b']==n[-2]['b']==9.5,'two notes together still make a chord')
    pg.evaluate("VR.ideas.press('iasong')");songs=pg.evaluate("VR.songs()")
    check(songs and songs[0]['title']=='Idea 3' and songs[0]['tracks']==1,f'💾 Save as a song puts it in My songs, a track for its pans {songs[:1]}')
    pg.evaluate("VR.ideas.press('iasong')");check(len(pg.evaluate("VR.songs()"))==len(songs),'saving again updates the same song')
    pg.evaluate("VR.ideas.press('iaclick')");check(pg.evaluate("VR.ideas.ia().click"),'🥁 Click starts a click to keep you steady')
    pg.wait_for_timeout(300);save('pad-auto')
    pg.evaluate("VR.ideas.press('iaclick')")
    # parts: another pan gets its own staff; play along; to and from the studio
    pg.evaluate("VR.ideas.press('ianew')")
    for i,(nid,beat) in enumerate([('tenor:72',0),('tenor:74',1),('tenor:76',2),('tenor:72',3)]):pg.evaluate(f"VR.ideas.hitAt('{nid}',{40+beat*B})")
    pg.evaluate(f"VR.ideas.hitAt('dsec:64',{60})");pg.evaluate(f"VR.ideas.hitAt('dsec:67',{60+B})")
    e=pg.evaluate("VR.ideas.state().list[0]");sets=[p['set'] for p in e['parts']]
    check(sets==['tenor','dsec'],f'a double seconds note starts a Double Second part under the tenor ({sets})')
    ds=e['parts'][1]['notes'];check(ds[0]['b']==0 and ds[1]['b']==1,'a new part starts at bar 1, beside the first')
    check(VR_clef:=pg.evaluate("(VR.ideas.press('iaclef:1'),VR.ideas.state().list[0].parts[1].clef)")=='bass','the 𝄞 button turns a part to the bass clef')
    pg.evaluate("VR.ideas.press('iaclef:1')")
    pg.evaluate("VR.ideas.press('iaplay')");t0=pg.evaluate("VR.ideas.ia().playT0")
    check(t0 is not None,'▶ with Writing on counts you in to play along')
    pg.evaluate(f"VR.ideas.hitAt('dsec:69',{t0}+2.02*{B})");pg.evaluate(f"VR.ideas.hitAt('dsec:71',{t0}+3*{B})")
    ds=[(n['m'],n['b']) for n in pg.evaluate("VR.ideas.state().list[0].parts[1].notes")]
    check((69,2) in ds and (71,3) in ds,f'playing along, notes go in at the beat they land on {ds}')
    pg.evaluate("VR.ideas.press('iaplay')");pg.wait_for_timeout(200);save('pad-parts')
    # a third pan: two parts show at a time, ▲▼ for the rest; chord names stack clear of the next part
    pg.evaluate("VR.ideas.hitAt('tenor:72',90);VR.ideas.hitAt('tenor:76',90.02);VR.ideas.hitAt('tenor:79',90.04)")
    pg.evaluate("VR.ideas.hitAt('six:40',95)");e=pg.evaluate("VR.ideas.state().list[0]")
    check([p['set'] for p in e['parts']]==['tenor','dsec','six'],'a six bass note adds a third part')
    hs=pg.evaluate("VR.ideas.hits()");check('iaps:1' in hs and 'iasel:2' in hs and 'iasel:0' not in hs,f'two parts show at a time, ▲▼ for the others')
    pg.evaluate("VR.ideas.press('iaps:-1')");save('pad-chord')
    pg.evaluate("VR.song().tracks.push({id:'tt',name:'Tenor',set:'tenor',vol:1,pan:0,mute:false,solo:false,col:'#fff',notes:[{id:'tenor:60',v:.8,b:0},{id:'tenor:64',v:.8,b:2},{id:'tenor:67',v:.8,b:2},{id:'tenor:72',v:.8,b:3}]})")
    n0=len(pg.evaluate("VR.ideas.state().list"));pg.evaluate("VR.ideas.press('iafrom')")
    e=pg.evaluate("VR.ideas.state().list[0]");check(len(pg.evaluate("VR.ideas.state().list"))==n0+1 and e['parts'][0]['set']=='tenor','⬇ From the studio makes a new idea with the song\'s tracks as parts')
    ns=[(n['m'],n['b'],n['d']) for n in e['parts'][0]['notes']];check(ns[:3]==[(60,0,2),(64,2,1),(67,2,1)],f'its notes keep their beats; each lasts until the next {ns}')
    pg.evaluate("VR.ideas.press('iaprev:1')");title=pg.evaluate("VR.ideas.state().list[1].title")
    pg.evaluate("VR.ideas.press('iaopen')");so=pg.evaluate("VR.song()")
    check(so['title']==title and sorted(t['set'] for t in so['tracks'])==['dsec','six','tenor'] and not pg.evaluate("VR.ideas.shown()"),f'🎹 Open as a song opens the parts as tracks in the studio ({so["title"]})')
    pg.evaluate("VR.ideas.open(true)")
    pg.evaluate("VR.ideas.press('iaclose')");check(not pg.evaluate("VR.ideas.shown()"),'✕ Close puts the pad away')
    hit('tenor:60');check(len(pg.evaluate("VR.ideas.state().list.find(e=>e.title=='Idea 1').notes"))==45,'with the pad away, playing writes nothing')
    pg.reload();load()
    st=pg.evaluate("VR.ideas.state()");check(len(st['list'])==5 and any(x['text'].startswith('C G Am') for x in st['list']),'ideas are kept on the headset')
    pg.evaluate("document.getElementById('hud').hidden=false;hudShow('#ideaBox')");pg.wait_for_timeout(200)
    rows=pg.evaluate("document.querySelectorAll('#ideaBox .idea').length");check(rows==5,'the page\'s Songs tab lists the ideas')
    pg.fill('#ideaBox .idea textarea','Typed on the page');check(pg.evaluate("VR.ideas.state().list[0].text")=='Typed on the page','and you can type an idea\'s notes there with a real keyboard')
    pg.screenshot(path=D+'page.png')
    check(not errs,f'no page errors {errs[:3]}')
    b.close()
print('FAILED: '+str(len(fails)) if fails else 'ALL OK');sys.exit(1 if fails else 0)
